a<-commandArgs(trailingOnly=TRUE);opts<-setNames(a[seq(2,length(a),2)],sub('^--','',a[seq(1,length(a),2)]));stopifnot(all(c('data-dir','output-dir','scenario','ibge-revision')%in%names(opts)))
cmd<-grep('^--file=',commandArgs(FALSE),value=TRUE);script<-normalizePath(sub('^--file=','',cmd));repo<-dirname(dirname(dirname(script)));.libPaths(c(file.path(repo,'revision/.Rlib'),.libPaths()));source(file.path(repo,'revision/scripts/analysis.R'));source(file.path(repo,'reanalysis/R/03_denominators.R'))
out<-opts[['output-dir']];dir.create(out,recursive=TRUE,showWarnings=FALSE);if(file.exists(file.path(out,'COMPLETE')))stop('Output already complete; choose a new directory.')
data<-normalizePath(opts[['data-dir']]);locked<-read.csv(file.path(repo,'revision/locked_inputs.csv'));for(i in seq_len(nrow(locked))){path<-file.path(if(locked$location[i]=='data')data else repo,locked$relative_path[i]);stopifnot(digest::digest(path,algo='sha256',file=TRUE)==locked$sha256[i])};write.csv(locked,file.path(out,'verified_inputs.csv'),row.names=FALSE);cfg<-scenario_config(opts[['scenario']]);capture.output(dput(c(cfg,list(ibge_revision=opts[['ibge-revision']],data_dir=data))),file=file.path(out,'configuration.R'));writeLines(capture.output(sessionInfo()),file.path(out,'session_info.txt'))
# Independently regenerated cache is keyed to whole CSV hashes and verified by the Python extractor.
cache<-file.path(repo,'revision/.cache');counts<-list();aggs<-list();records<-list();overlaps<-list()
raw_counts<-read.csv(file.path(cache,'raw_counts.csv'))
for(y in 2014:2021){d<-read.csv(file.path(cache,paste0('asthma_',y,'.csv')),colClasses='character',na.strings=c('','NA'),check.names=FALSE);r<-select_records(d,y,cfg,raw_counts$N_raw[raw_counts$year==y]);counts[[as.character(y)]]<-r$counts;aggs[[as.character(y)]]<-r$agg;records[[as.character(y)]]<-r$records;overlaps[[as.character(y)]]<-r$overlap}
agg<-do.call(rbind,aggs);write.csv(do.call(rbind,counts),file.path(out,'selection_counts.csv'),row.names=FALSE);write.csv(do.call(rbind,overlaps),file.path(out,'covid_overlap_patterns.csv'),row.names=FALSE);write.csv(do.call(rbind,records),file.path(out,'record_selection_and_age_transitions.csv'),row.names=FALSE);write.csv(agg,file.path(out,'annual_aggregates.csv'),row.names=FALSE)
revision<-opts[['ibge-revision']];stopifnot(revision%in%c('2018','2024'))
pop<-if(revision=='2018')reconstruct_ibge_denominators(file.path(data,'raw/projecoes_2018_populacao_idade_simples_2010_2060_20201209.xls'))$by_age else read2024(file.path(repo,'revision/inputs/projecoes_2024_tab1_idade_simples.xlsx'))
write.csv(pop,file.path(out,'population_by_age.csv'),row.names=FALSE);rates<-make_rates(agg,pop,cfg$years);write.csv(rates$series,file.path(out,'rates_by_year.csv'),row.names=FALSE);write.csv(rates$weights,file.path(out,'standard_weights.csv'),row.names=FALSE);write.csv(trend_summary(rates$series),file.path(out,'rate_trends.csv'),row.names=FALSE)
models<-fit_counts(agg,pop,cfg$years,rates$count_data);write.csv(models$summary,file.path(out,'count_models.csv'),row.names=FALSE);write.csv(models$coefficients,file.path(out,'count_coefficients.csv'),row.names=FALSE);saveRDS(models$fits,file.path(out,'count_fits.rds'));saveRDS(models$inputs,file.path(out,'count_inputs.rds'))
k<-kitagawa(agg,pop,cfg$years);write.csv(k$summary,file.path(out,'kitagawa_endpoints.csv'),row.names=FALSE);write.csv(k$details,file.path(out,'kitagawa_age_contributions.csv'),row.names=FALSE)
write.csv(as.data.frame(installed.packages()[,c('Package','Version')]),file.path(out,'package_versions.csv'),row.names=FALSE);writeLines(format(Sys.time(),tz='UTC'),file.path(out,'COMPLETE'));message('Completed ',cfg$scenario,' IBGE ',revision)
